class MovingAverageFilter {
private:
    vector<double> sampleWindow;
    size_t nextSampleIndex = 0;
    double runningSum = 0.0;

public:
    explicit MovingAverageFilter(size_t windowLength) {
        if (windowLength == 0) throw invalid_argument("windowLength deve ser maior que zero");
        sampleWindow.assign(windowLength, 0.0);
    }

    double processSample(double newSample) {
        runningSum -= sampleWindow[nextSampleIndex];
        sampleWindow[nextSampleIndex] = newSample;
        runningSum += newSample;
        nextSampleIndex = (nextSampleIndex + 1) % sampleWindow.size();
        return runningSum / sampleWindow.size();
    }
};
